{
    "ruleName": "住院医保报销规则（更新）",
    "ruleText": "package com.his.rules

rule "住院医保报销规则"
    salience 100
    when
        : SettlementFact(patientType == "INPATIENT")
    then
        .setReimburseAmount(.getTotalFee().multiply(new java.math.BigDecimal("0.80")));
end",
    "description": "住院患者医保报销比例调整为80%",
    "salience": 100
}

{
    "flowKey": "flow.settlement.inpatient",
    "flowName": "住院结算流程",
    "category": "settlement",
    "description": "住院患者医保结算流程：身份校验→起付线→报销比例→金额计算",
    "flowDefinition": {
        "nodes": [
            {
                "nodeId": "start",
                "type": "start",
                "label": "开始",
                "x": 100,
                "y": 200
            },
            {
                "nodeId": "check_identity",
                "type": "action",
                "label": "医保身份校验",
                "ruleKey": "rule.insurance.identity",
                "x": 300,
                "y": 200
            },
            {
                "nodeId": "calc_deductible",
                "type": "formula",
                "label": "计算起付线",
                "formulaKey": "formula.deductible",
                "x": 500,
                "y": 200
            },
            {
                "nodeId": "calc_reimburse",
                "type": "formula",
                "label": "计算报销金额",
                "formulaKey": "formula.reimburse",
                "x": 700,
                "y": 200
            },
            {
                "nodeId": "end",
                "type": "end",
                "label": "结束",
                "x": 900,
                "y": 200
            }
        ],
        "edges": [
            {
                "source": "start",
                "target": "check_identity"
            },
            {
                "source": "check_identity",
                "target": "calc_deductible"
            },
            {
                "source": "calc_deductible",
                "target": "calc_reimburse"
            },
            {
                "source": "calc_reimburse",
                "target": "end"
            }
        ]
    }
}

